import type { DndObserver } from 'dragdoll/dnd-observer';
import type { Accessor } from 'solid-js';
import { useContext } from 'solid-js';
import { DndObserverContext } from '../contexts/dnd-observer-context.js';

export function useDndObserverContext<T extends DndObserver | null = DndObserver | null>() {
  return useContext(DndObserverContext) as Accessor<T>;
}
